const { storeDeviceStateToCacheAsync } = global.get('helpers');

// The VKT-7 sends values in the units set in the calculator (see
// msg.payload.units): this one is set to Гкал and кг/см², as the state keeps.
// Fields as the old dispatch system shows channel "VKT7-141425 / ЦО".
const { input1, firmware, deviceTime } = msg.payload;

const deviceState = {
    // Heat input 1 (ЦО, scheme 4): t1/G1/V1/M1 are the supply, t2/M2 the
    // return (the return has no flow meter: its mass comes from G1 and t2).

    // Temperature, °C
    temperatureInputPipe: input1.t1,     // supply water temperature
    temperatureReturnPipe: input1.t2,    // return water temperature

